// ------------------------------------------------------------------ servers
function makeServer() {
  const s = http.createServer((req, res) => {
    if (!core.handle(req, res, dev)) { res.writeHead(404); res.end('Not Found'); }
  });
  s.on('upgrade', (req, socket) => { if (!core.upgrade(req, socket, dev)) refuseUpgrade(socket, 404); });
  return s;
}
function listen(s, port) {
  return new Promise(resolve => {
    s.once('error', e => resolve(e.code || String(e)));
    s.listen(port, '127.0.0.1', () => resolve(null));
  });
}

// raw HTTP request (no automatic decompression)
function request(p, opt = {}) {
  return new Promise((resolve, reject) => {
    const body = opt.body === undefined ? null : Buffer.from(typeof opt.body === 'string' ? opt.body : JSON.stringify(opt.body));
    const req = http.request({ host: '127.0.0.1', port: opt.port || PORT, path: p, method: opt.method || (body ? 'POST' : 'GET'),
      headers: Object.assign(body ? { 'Content-Type': 'application/json', 'Content-Length': body.length } : {}, opt.headers) }, res => {
      const parts = [];
      res.on('data', d => parts.push(d));
      res.on('end', () => resolve({ status: res.statusCode, headers: res.headers, body: Buffer.concat(parts) }));
    });
    req.on('error', reject);
    if (body) req.write(body);
    req.end();
  });
}
const json = r => JSON.parse(r.body.toString('utf8'));

// PAGE_x bytes parsed straight from the generated header (independent of extract.js)
function headerArray(file, name) {
  const t = fs.readFileSync(path.join(HDR_DIR, file), 'utf8');
  const m = new RegExp(`const uint16_t ${name}_length = (\\d+);\\s*const uint8_t ${name}\\[\\] PROGMEM = \\{([\\s\\S]*?)\\};`).exec(t);
  if (!m) return null;
  return { length: +m[1], bytes: Buffer.from(m[2].match(/0x[0-9a-fA-F]{2}/g).map(h => parseInt(h, 16))) };
}

