// ------------------------------------------------------------------ websocket checks (Node 22+ global WebSocket)
async function wsTests() {
  if (typeof WebSocket !== 'function') { check('global WebSocket available', false, 'Node ' + process.version); return; }
  for (const p of ['/ws', '/wled/ws']) {
    const msgs = [], bins = [];
    const ws = new WebSocket(`ws://127.0.0.1:${PORT}${p}`);
    ws.binaryType = 'arraybuffer';
    ws.onmessage = e => { if (typeof e.data === 'string') msgs.push(JSON.parse(e.data)); else bins.push(new Uint8Array(e.data)); };
    await new Promise((res, rej) => { ws.onopen = res; ws.onerror = () => rej(new Error('ws error')); });
    await sleep(200);
    check(`${p}: first message is {state, info}`, msgs[0] && msgs[0].state && msgs[0].info && Array.isArray(msgs[0].state.seg));
    ws.send('{"lv":true}');
    await sleep(1000);
    const n1 = bins.length, f = bins[0];
    check(`${p}: 'L' frames after {"lv":true}`, n1 >= 15 && f && f[0] === 76 && f[1] === 1 && f.length === 2 + 3 * dev.LEDS,
      `${n1} frames/s, ${f && f.length} B`);
    const lit = f ? f.slice(2).some(b => b > 0) : false;
    check(`${p}: live frames carry colour`, lit);
    ws.send('{"lv":false}');
    await sleep(300);
    const n2 = bins.length;
    await sleep(400);
    check(`${p}: frames stop after {"lv":false}`, bins.length === n2, `${bins.length - n2} extra`);
    const before = msgs.length;
    ws.send(JSON.stringify({ bri: 90, v: true }));
    await sleep(1300);
    const pushed = msgs.slice(before).find(m => m.state && m.state.bri === 90);
    check(`${p}: a state change is pushed back`, !!pushed && dev.state().bri === 90);
    ws.send('{"v":true}');
    await sleep(200);
    check(`${p}: {"v":true} -> state+info reply`, msgs.length > before + 1 && msgs[msgs.length - 1].info);
    ws.close();
    await sleep(100);
  }
}

